CREATE TABLE premium_employees(id TEXT PRIMARY KEY,operator_id TEXT NOT NULL REFERENCES operators(id),user_id TEXT REFERENCES users(id),revision INTEGER NOT NULL DEFAULT 1,last_request TEXT NOT NULL DEFAULT '',full_name TEXT NOT NULL,job_title TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',base_pay_cents INTEGER NOT NULL CHECK(base_pay_cents>=0),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','inactive')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX premium_employee_tenant ON premium_employees(operator_id,id);
CREATE TABLE premium_shifts(id TEXT PRIMARY KEY,operator_id TEXT NOT NULL REFERENCES operators(id),employee_id TEXT NOT NULL REFERENCES premium_employees(id),vehicle_id TEXT REFERENCES vehicles(id),starts_at INTEGER NOT NULL,ends_at INTEGER NOT NULL CHECK(ends_at>starts_at),notes TEXT NOT NULL DEFAULT '',last_request TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN('scheduled','active','completed','cancelled')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER premium_shift_scope BEFORE INSERT ON premium_shifts WHEN NOT EXISTS(SELECT 1 FROM premium_employees e WHERE e.id=NEW.employee_id AND e.operator_id=NEW.operator_id AND e.status='active') OR (NEW.vehicle_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM vehicles WHERE id=NEW.vehicle_id AND operator_id=NEW.operator_id)) OR EXISTS(SELECT 1 FROM premium_shifts s WHERE s.status IN('scheduled','active') AND (s.employee_id=NEW.employee_id OR s.vehicle_id=NEW.vehicle_id) AND s.starts_at<NEW.ends_at AND s.ends_at>NEW.starts_at)
BEGIN SELECT RAISE(ABORT,'shift_conflict'); END;
CREATE TABLE premium_partners(id TEXT PRIMARY KEY,operator_id TEXT NOT NULL REFERENCES operators(id),revision INTEGER NOT NULL DEFAULT 1,last_request TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL CHECK(kind IN('customer','supplier')),name TEXT NOT NULL,tax_id TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX premium_partner_tenant ON premium_partners(operator_id,id);
CREATE TABLE premium_business_documents(id TEXT PRIMARY KEY,operator_id TEXT NOT NULL REFERENCES operators(id),kind TEXT NOT NULL CHECK(kind IN('receivable','payable')),partner_id TEXT REFERENCES premium_partners(id),vehicle_id TEXT REFERENCES vehicles(id),offer_id TEXT REFERENCES route_offers(id),booking_id TEXT REFERENCES bookings(id),expense_id TEXT UNIQUE REFERENCES premium_expenses(id),payroll_id TEXT UNIQUE,reference TEXT NOT NULL,description TEXT NOT NULL,issued_on TEXT NOT NULL,due_on TEXT NOT NULL,subtotal_cents INTEGER NOT NULL CHECK(subtotal_cents>0),tax_cents INTEGER NOT NULL CHECK(tax_cents>=0),amount_cents INTEGER NOT NULL CHECK(amount_cents=subtotal_cents+tax_cents),lines_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','void')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX premium_business_documents_tenant ON premium_business_documents(operator_id,due_on,id);
CREATE UNIQUE INDEX premium_document_reference ON premium_business_documents(operator_id,kind,partner_id,reference);
CREATE TRIGGER premium_document_scope BEFORE INSERT ON premium_business_documents WHEN (NEW.partner_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM premium_partners WHERE id=NEW.partner_id AND operator_id=NEW.operator_id AND kind=CASE WHEN NEW.kind='receivable' THEN 'customer' ELSE 'supplier' END)) OR (NEW.vehicle_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM vehicles WHERE id=NEW.vehicle_id AND operator_id=NEW.operator_id)) OR (NEW.offer_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM route_offers WHERE id=NEW.offer_id AND operator_id=NEW.operator_id)) OR (NEW.booking_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM standard_booking_details WHERE booking_id=NEW.booking_id AND operator_id=NEW.operator_id)) OR (NEW.expense_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM premium_expenses WHERE id=NEW.expense_id AND operator_id=NEW.operator_id AND status='posted'))
BEGIN SELECT RAISE(ABORT,'enterprise_scope'); END;
CREATE TABLE premium_business_payments(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES premium_business_documents(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),kind TEXT NOT NULL CHECK(kind IN('payment','reversal')),reverse_of TEXT UNIQUE REFERENCES premium_business_payments(id),reference TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),simulation INTEGER NOT NULL DEFAULT 1 CHECK(simulation=1),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER premium_business_payment_guard BEFORE INSERT ON premium_business_payments WHEN NOT EXISTS(SELECT 1 FROM premium_business_documents WHERE id=NEW.document_id AND status='open') OR (NEW.kind='payment' AND (NEW.reverse_of IS NOT NULL OR NEW.amount_cents+COALESCE((SELECT SUM(CASE WHEN kind='payment' THEN amount_cents ELSE -amount_cents END) FROM premium_business_payments WHERE document_id=NEW.document_id),0)>(SELECT amount_cents FROM premium_business_documents WHERE id=NEW.document_id))) OR (NEW.kind='reversal' AND NOT EXISTS(SELECT 1 FROM premium_business_payments p WHERE p.id=NEW.reverse_of AND p.kind='payment' AND p.document_id=NEW.document_id AND p.amount_cents=NEW.amount_cents))
BEGIN SELECT RAISE(ABORT,'enterprise_payment_conflict'); END;
CREATE TRIGGER premium_business_payment_immutable BEFORE UPDATE ON premium_business_payments BEGIN SELECT RAISE(ABORT,'immutable_financial_event'); END;
CREATE TRIGGER premium_business_payment_no_delete BEFORE DELETE ON premium_business_payments BEGIN SELECT RAISE(ABORT,'immutable_financial_event'); END;
CREATE TRIGGER premium_business_void_guard BEFORE UPDATE OF status ON premium_business_documents WHEN NEW.status='void' AND COALESCE((SELECT SUM(CASE WHEN kind='payment' THEN amount_cents ELSE -amount_cents END) FROM premium_business_payments WHERE document_id=OLD.id),0)>0
BEGIN SELECT RAISE(ABORT,'enterprise_payment_conflict'); END;
CREATE TABLE premium_payroll_runs(id TEXT PRIMARY KEY,operator_id TEXT NOT NULL REFERENCES operators(id),starts_on TEXT NOT NULL,ends_on TEXT NOT NULL,total_cents INTEGER NOT NULL CHECK(total_cents>=0),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','posted','void')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE premium_payroll_lines(run_id TEXT NOT NULL REFERENCES premium_payroll_runs(id),employee_id TEXT NOT NULL REFERENCES premium_employees(id),base_cents INTEGER NOT NULL CHECK(base_cents>=0),extra_cents INTEGER NOT NULL CHECK(extra_cents>=0),deduction_cents INTEGER NOT NULL CHECK(deduction_cents>=0),net_cents INTEGER NOT NULL CHECK(net_cents=base_cents+extra_cents-deduction_cents AND net_cents>=0),PRIMARY KEY(run_id,employee_id));
CREATE TRIGGER premium_payroll_scope BEFORE INSERT ON premium_payroll_lines WHEN NOT EXISTS(SELECT 1 FROM premium_employees e JOIN premium_payroll_runs r ON r.operator_id=e.operator_id WHERE r.id=NEW.run_id AND e.id=NEW.employee_id AND e.status='active') OR EXISTS(SELECT 1 FROM premium_payroll_lines l JOIN premium_payroll_runs r ON r.id=l.run_id JOIN premium_payroll_runs n ON n.id=NEW.run_id WHERE l.employee_id=NEW.employee_id AND r.status<>'void' AND r.starts_on<=n.ends_on AND r.ends_on>=n.starts_on)
BEGIN SELECT RAISE(ABORT,'payroll_conflict'); END;
CREATE TABLE premium_component_plans(id TEXT PRIMARY KEY,operator_id TEXT NOT NULL REFERENCES operators(id),vehicle_id TEXT NOT NULL REFERENCES vehicles(id),component TEXT NOT NULL CHECK(component IN('oil','tires','brakes','documentation','other')),revision INTEGER NOT NULL DEFAULT 1,last_request TEXT NOT NULL DEFAULT '',label TEXT NOT NULL,due_km INTEGER,due_on TEXT,interval_km INTEGER,interval_days INTEGER,last_done_km INTEGER,last_done_on TEXT);
CREATE TABLE premium_odometer_history(id INTEGER PRIMARY KEY AUTOINCREMENT,vehicle_id TEXT NOT NULL REFERENCES vehicles(id),odometer_km INTEGER NOT NULL,recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO premium_odometer_history(vehicle_id,odometer_km,recorded_at) SELECT vehicle_id,odometer_km,updated_at FROM premium_vehicle_profiles;
CREATE TRIGGER premium_odometer_history_insert AFTER INSERT ON premium_vehicle_profiles BEGIN INSERT INTO premium_odometer_history(vehicle_id,odometer_km) VALUES(NEW.vehicle_id,NEW.odometer_km); END;
CREATE TRIGGER premium_odometer_history_update AFTER UPDATE OF odometer_km ON premium_vehicle_profiles WHEN NEW.odometer_km<>OLD.odometer_km BEGIN INSERT INTO premium_odometer_history(vehicle_id,odometer_km) VALUES(NEW.vehicle_id,NEW.odometer_km); END;
ALTER TABLE premium_maintenance ADD COLUMN component_plan_id TEXT REFERENCES premium_component_plans(id);
CREATE TRIGGER premium_component_completed AFTER UPDATE OF status ON premium_maintenance WHEN NEW.status='completed' AND OLD.status='open' AND NEW.component_plan_id IS NOT NULL
BEGIN UPDATE premium_component_plans SET last_done_on=date('now'),last_done_km=(SELECT odometer_km FROM premium_vehicle_profiles WHERE vehicle_id=NEW.vehicle_id),due_km=CASE WHEN interval_km IS NOT NULL AND EXISTS(SELECT 1 FROM premium_vehicle_profiles WHERE vehicle_id=NEW.vehicle_id) THEN interval_km+(SELECT odometer_km FROM premium_vehicle_profiles WHERE vehicle_id=NEW.vehicle_id) ELSE due_km END,due_on=CASE WHEN interval_days IS NOT NULL THEN date('now','+'||interval_days||' days') ELSE due_on END WHERE id=NEW.component_plan_id AND operator_id=NEW.operator_id AND vehicle_id=NEW.vehicle_id; END;
ALTER TABLE settlements ADD COLUMN simulation INTEGER NOT NULL DEFAULT 1 CHECK(simulation=1);
ALTER TABLE bookings ADD COLUMN sales_channel TEXT NOT NULL DEFAULT 'marketplace' CHECK(sales_channel IN('marketplace','office'));
CREATE TABLE premium_settlement_custom_items(settlement_id TEXT NOT NULL REFERENCES settlements(id),custom_booking_id TEXT NOT NULL UNIQUE REFERENCES standard_custom_bookings(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>=0),PRIMARY KEY(settlement_id,custom_booking_id));
CREATE TABLE premium_enterprise_assertions(id TEXT PRIMARY KEY,operator_id TEXT NOT NULL,entity_kind TEXT NOT NULL,entity_id TEXT NOT NULL,request_id TEXT NOT NULL,revision INTEGER NOT NULL,state TEXT);
CREATE TRIGGER premium_enterprise_cas BEFORE INSERT ON premium_enterprise_assertions WHEN (NEW.entity_kind='employee' AND NOT EXISTS(SELECT 1 FROM premium_employees WHERE id=NEW.entity_id AND operator_id=NEW.operator_id AND revision=NEW.revision AND last_request=NEW.request_id)) OR (NEW.entity_kind='partner' AND NOT EXISTS(SELECT 1 FROM premium_partners WHERE id=NEW.entity_id AND operator_id=NEW.operator_id AND revision=NEW.revision AND last_request=NEW.request_id)) OR (NEW.entity_kind='component' AND NOT EXISTS(SELECT 1 FROM premium_component_plans WHERE id=NEW.entity_id AND operator_id=NEW.operator_id AND revision=NEW.revision AND last_request=NEW.request_id)) OR (NEW.entity_kind='shift' AND NOT EXISTS(SELECT 1 FROM premium_shifts WHERE id=NEW.entity_id AND operator_id=NEW.operator_id AND status=NEW.state AND last_request=NEW.request_id)) OR (NEW.entity_kind='issuer' AND NOT EXISTS(SELECT 1 FROM premium_fiscal_settings WHERE operator_id=NEW.operator_id AND revision=NEW.revision AND last_request=NEW.request_id))
BEGIN SELECT RAISE(ABORT,'enterprise_cas'); END;
CREATE TRIGGER premium_employee_active_guard BEFORE UPDATE OF status,user_id ON premium_employees WHEN (NEW.status='inactive' OR NEW.user_id IS NOT OLD.user_id) AND EXISTS(SELECT 1 FROM premium_shifts WHERE employee_id=OLD.id AND status='active')
BEGIN SELECT RAISE(ABORT,'shift_conflict'); END;
CREATE TRIGGER premium_shift_activation_guard BEFORE UPDATE OF status ON premium_shifts WHEN NEW.status='active' AND NOT EXISTS(SELECT 1 FROM premium_employees WHERE id=NEW.employee_id AND operator_id=NEW.operator_id AND status='active')
BEGIN SELECT RAISE(ABORT,'shift_conflict'); END;
CREATE TRIGGER premium_expense_link_guard BEFORE UPDATE OF status ON premium_expenses WHEN NEW.status='void' AND EXISTS(SELECT 1 FROM premium_business_documents WHERE expense_id=OLD.id AND status='open')
BEGIN SELECT RAISE(ABORT,'expense_linked'); END;
CREATE TABLE premium_fiscal_settings(operator_id TEXT PRIMARY KEY REFERENCES operators(id),address TEXT NOT NULL,establishment TEXT NOT NULL,emission_point TEXT NOT NULL,environment TEXT NOT NULL DEFAULT 'test' CHECK(environment='test'),revision INTEGER NOT NULL,last_request TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migrations(version) VALUES('0028_enterprise_management');
